extracted_python_code:
result = Broker.CALCULATE(
    num_faang_customers_with_com_email=COUNT(
        Customers.WHERE(
            (ENDSWITH(email, ".com")) &
            (HAS(transactions_made.WHERE(ISIN(ticker.symbol, ("AMZN", "AAPL", "GOOGL", "META", "NFLX")))) == 1)
        )
    )
)

filtered_customers = Customers.WHERE(
    (
        STARTSWITH(LOWER(name), "j") | ENDSWITH(LOWER(name), "ez")
    ) &
    ENDSWITH(LOWER(state), "a")
)
result = Broker.CALCULATE(
    num_matching_customers=COUNT(filtered_customers)
)

distinct_ticker_ids_on_or_after_date = Tickers.WHERE(
    HAS(historical_prices.WHERE(date >= "2023-04-01")) == 1
).CALCULATE(
    ticker_id=_id
)

transactions_from_recent_customers = Broker.CALCULATE(
    num_transactions_recent_joiners=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, 'now') <= 70
        ).transactions_made
    )
)

sales_by_model_with_m5_vin = Cars.WHERE(
    LIKE(vin_number, '%M5%')  # Filter cars where VIN contains 'M5' (case-insensitive partial match)
).PARTITION(
    name="car_model_group", by=(make, model)  # Group filtered cars by make and model
).CALCULATE(
    car_make=make,  # Select the make from the partition key
    car_model=model,  # Select the model from the partition key
    number_of_sales=COUNT(Cars.sale_records)  # Count all sales for cars in this make/model group
)

asp_q1_2023 = Dealership.CALCULATE(
    average_sale_price_q1_2023=AVG(
        Sales.WHERE(
            (YEAR(sale_date) == 2023) & 
            (ISIN(MONTH(sale_date), (1, 2, 3)))
        ).sale_price
    )
)

average_payment_lag_days = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

result = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((snapshot_date == sale_date) & (is_in_inventory == False))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    car_make=car.make,
    car_model=car.model,
    sale_price=sale_price
)

distinct_customer_ids_with_purchases = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

salespersons_with_cash_payments_ids = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == "cash")) == 1
).CALCULATE(
    salesperson_id=_id
)

weekend_payments_to_utility_company = Dealership.CALCULATE(
    num_weekend_payments_utility_co=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') &
            (ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday')))
        )
    )
)

patients_with_gmail_or_yahoo = Patients.WHERE(
    ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
)
result = DermTreatment.CALCULATE(
    count_patients_gmail_yahoo=COUNT(patients_with_gmail_or_yahoo)
)

result = DermTreatment.CALCULATE(
    num_patients_diag_drug = COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'Biologic')
                )
            ) == 1
        )
    )
)

avg_weight_result = DermTreatment.CALCULATE(
    average_weight_kg_for_drugalin_patients=AVG(
        Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg
    )
)

result = DermTreatment.CALCULATE(
    caw_male_patients = AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

pic_female_patients = DermTreatment.CALCULATE(
    private_insured_female_patient_count=COUNT(
        Patients.WHERE((gender == "Female") & (ins_type == "Private"))
    )
)

# Filter doctors who have prescribed biologic drugs
biologic_prescribing_doctors = Doctors.WHERE(
    HAS(prescribed_treatments.drug.WHERE(drug_type == 'biologic')) == 1
)

# Get the distinct states of these doctors
distinct_states_of_doctors = biologic_prescribing_doctors.PARTITION(
    name="states_group", by=(loc_state)
).CALCULATE(
    doctor_state=loc_state
)

result = DermTreatment.CALCULATE(
    avg_male_patient_age_private_ins=ROUND(
        AVG(
            Patients.WHERE(
                (gender == "Male") & (ins_type == "Private")
            ).CALCULATE(
                current_age=DATEDIFF("years", date_of_birth, DATETIME('now'))
            ).current_age
        )
    )
)

active_retail_merchants_with_coupons = Merchants.WHERE(
    (status == 'active') & (LOWER(category) == 'retail') & (HAS(coupons) == 1)
).CALCULATE(
    merchant_name=name,
    total_coupons_issued=COUNT(coupons)
)

user_marketing_preferences = Users.CALCULATE(
    user_id_val=uid,
    opt_in_status=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Users.WHERE(
    (LOWER(country) == 'us') &
    (HAS(notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))) == 1)
).CALCULATE(
    username = username,
    total_unread_promotional_notifications = COUNT(
        notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))
    )
)

distinct_user_ids_with_notifications = Users.WHERE(HAS(notifications)==1).CALCULATE(
    user_id=uid
)

avg_session_duration_by_device_type = UserSessions.PARTITION(name="sessions_by_device_type", by=(device_type)).CALCULATE(
    device_type = device_type,
    avg_session_duration_seconds = AVG(
        DATEDIFF("seconds", UserSessions.session_start_ts, UserSessions.session_end_ts)
    )
)

users_without_early_notifications = Users.WHERE(
    HASNOT(
        notifications.WHERE(created_at < DATETIME(Users.created_at, '+1 year'))
    ) == 1
).CALCULATE(
    user_name=username,
    user_email=email,
    signup_date=created_at
)
